-- 夹具取自本机真实的 ZCode 库（~/.zcode/cli/db/db.sqlite，363 MB）：
-- session + message + part 三张表（与 OpenCode 的旧格式同一路子）。
-- 只裁掉体积大的字段（tokens、signature、工具输出的尾巴），文案与结构保持原样。
create table session (id text primary key, project_id text, slug text, directory text, title text, version text, time_created integer, time_updated integer, task_type text);
create table message (id text primary key, session_id text, time_created integer, time_updated integer, data text, sequence integer);
create table part (id text primary key, message_id text, session_id text, time_created integer, time_updated integer, data text, sequence integer);
